{
  "name": "edgent-smith dev",
  "dockerComposeFile": "docker-compose.yml",
  "service": "devcontainer",
  "workspaceFolder": "/workspace",
  "features": {
    "ghcr.io/devcontainers/features/git:1.3.8": {},
    "ghcr.io/devcontainers/features/github-cli:1": {},
    "ghcr.io/devcontainers/features/node:2.1.0": {
      "version": "24"
    },
    "ghcr.io/devcontainers/features/python:1": {
      "version": "3.14"
    },
    "ghcr.io/devcontainer-community/devcontainer-features/astral.sh-uv:1": {},
    "ghcr.io/jsburckhardt/devcontainer-features/just:1": {},
    "ghcr.io/devcontainers-extra/features/bun:1": {
      "version": "latest"
    },
    "ghcr.io/devcontainers-extra/features/opencode:1": {}
  },
  "customizations": {
    "vscode": {
      "extensions": [
        "ms-python.python",
        "ms-python.mypy-type-checker",
        "charliermarsh.ruff",
        "tamasfe.even-better-toml"
      ],
      "settings": {
        "python.defaultInterpreterPath": "${workspaceFolder}/.venv/bin/python",
        "python.terminal.activateEnvInCurrentTerminal": true,
        "editor.formatOnSave": true,
        "[python]": {
          "editor.defaultFormatter": "charliermarsh.ruff"
        }
      }
    }
  },
  "containerEnv": {
    "BUN_INSTALL": "/home/vscode/.bun",
    "OPENCODE_DATA_DIR": "/home/vscode/.local/share/opencode",
    "PATH": "/home/vscode/.opencode/bin:/home/vscode/.bun/bin:${localEnv:PATH}"
  },
  "initializeCommand": "if [ \"${CI}\" != \"true\" ] && ! grep -q '^COMPOSE_PROFILES=' .devcontainer/.env 2>/dev/null; then echo 'COMPOSE_PROFILES=infra' >> .devcontainer/.env; fi",
  "postCreateCommand": "bash .devcontainer/setup-dev.sh",
  "remoteUser": "vscode",
  "forwardPorts": [
    8000,
    11434,
    16686,
    4318
  ],
  "portsAttributes": {
    "8000": {
      "label": "edgent-smith API"
    },
    "11434": {
      "label": "Ollama"
    },
    "16686": {
      "label": "Jaeger UI"
    },
    "4318": {
      "label": "Jaeger OTLP HTTP"
    }
  }
}
